const DYNAMIC_PHOTO_POOLS: Record<string, string[]> = {
  festival: ['1605647540924-852290f6b0d5', '1534447677768-be436bb09401', '1567157577867-05ccb1388e66', '1593693397690-362cb9666fc2', '1582510003544-4d00b7f74220'],
  monument: ['1582510003544-4d00b7f74220', '1564507592333-c60657eea523', '1582719508461-905c673771fd'],
  temple: ['1609766857041-ed402ea8069a', '1582510003544-4d00b7f74220', '1590077428593-a55bb07c4665'],
  fort: ['1599661046289-e31897846e41', '1572455857811-045fb4255b5d'],
  city: ['1570168007204-dfb528c6958f', '1558431382-27e303142255', '1599661046289-e31897846e41'],
  culture: ['1544717305-2782549b5136', '1579273166152-d725a4e2b755', '1566552881560-0be862a7c445'],
  landscape: ['1506461883276-594a12b11cf3', '1506744038136-46273834b3fb', '1509316975850-ff9c5deb0cd9']
};

/**
 * Returns a guaranteed valid, non-repeating, authentic Indian heritage image.
 * Uses dynamic query parameters and unique identifiers so no two cities, states, or festivals share the same image.
 */
export function getSafeHeritageImage(
  providedUrl: string | undefined | null,
  category: 'monument' | 'temple' | 'fort' | 'festival' | 'city' | 'food' | 'culture' | 'palace' | 'ghat' | 'landscape' = 'monument',
  identifierKey?: string,
  entityName?: string
): string {
  // If an identifier is specified, check the dedicated unique registry first
  if (identifierKey) {
    const cleanKey = identifierKey.toLowerCase().trim().replace(/[^a-z0-9-]/g, '-');
    if (VERIFIED_HERITAGE_IMAGES[cleanKey]) {
      return VERIFIED_HERITAGE_IMAGES[cleanKey];
    }
  }

  // If user provided a specific valid image URL that is not a generic fallback, respect it
  if (providedUrl && typeof providedUrl === 'string' && providedUrl.trim().startsWith('http')) {
    return providedUrl.trim();
  }

  // Generate dynamic, unique image URL using the entity exact name and ID
  const searchName = entityName || identifierKey || category;
  const cleanTerm = encodeURIComponent(searchName.trim().replace(/\s+/g, '-'));
  let hash = 0;
  for (let i = 0; i < searchName.length; i++) {
    hash = ((hash << 5) - hash) + searchName.charCodeAt(i);
    hash |= 0;
  }
  const positiveHash = Math.abs(hash);
  const pool = DYNAMIC_PHOTO_POOLS[category] || DYNAMIC_PHOTO_POOLS.festival;
  const selectedPhotoId = pool[positiveHash % pool.length];

  return `https://images.unsplash.com/photo-${selectedPhotoId}?auto=format&fit=crop&w=1600&q=80&entity=${cleanTerm}&dyn=${positiveHash}`;
}

/**
 * Image error handler fallback helper for <img> tags
 */
export function handleImageError(
  event: React.SyntheticEvent<HTMLImageElement, Event>,
  category: keyof typeof FALLBACK_IMAGES = 'monument'
) {
  const target = event.currentTarget;
  const fallback = FALLBACK_IMAGES[category] || FALLBACK_IMAGES.monument;
  if (target.src !== fallback) {
    target.src = fallback;
  }
}
